properties.query:
// Detects completion of a Global Administrator role change - either a PIM (Privileged Identity
// Management) self-activation or a direct/permanent role assignment - against the AuditLogs
// table only (single-table query, required for an NRT rule). Deeper correlation (who approved
// the PIM request, and what the account then did while elevated) is deliberately NOT attempted
// here - that needs a join across the activation/approval audit events and a lookback window,
// which belongs in the downstream playbook (LogicApp/NotifySocTeams), not in a 60-second NRT
// query. This rule's job is only to fire fast and hand the playbook a RequestId to join on.
//
// NOTE: exact OperationName strings and AdditionalDetails key names for PIM audit events are
// documented by Microsoft but can vary slightly by tenant / Entra ID role management module
// version. Validate against a sample of AuditLogs in your own workspace before enabling in
// production - see AnalyticsRules/GlobalAdminRoleUsage/README.md.
AuditLogs
| where TimeGenerated > ago(15m)
| where Category == "RoleManagement"
| where OperationName in (
    "Add member to role completed (PIM activation)",
    "Add member to role"
)
| mv-expand TargetResources
| where TargetResources.type == "Role"
| mv-expand ModifiedProperty = TargetResources.modifiedProperties
| where ModifiedProperty.displayName == "Role.DisplayName"
| where tostring(ModifiedProperty.newValue) has "Global Administrator"
| mv-expand AdditionalDetail = AdditionalDetails
| extend DetailKey = tostring(AdditionalDetail.key), DetailValue = tostring(AdditionalDetail.value)
| summarize AdditionalMap = make_bag(pack(DetailKey, DetailValue))
    by TimeGenerated, OperationName, Result, CorrelationId,
       TargetUser = tostring(TargetResources.userPrincipalName),
       TargetUserId = tostring(TargetResources.id),
       InitiatingActor = tostring(InitiatedBy.user.userPrincipalName),
       InitiatingActorId = tostring(InitiatedBy.user.id),
       InitiatingIp = tostring(InitiatedBy.user.ipAddress)
| extend ActivationType = iif(OperationName == "Add member to role completed (PIM activation)", "PIM-Activation", "Direct-Assignment")
| extend RequestId = tostring(AdditionalMap.RequestId)
| project TimeGenerated, OperationName, ActivationType, Result, CorrelationId, RequestId,
    TargetUser, TargetUserId, InitiatingActor, InitiatingActorId, InitiatingIp
